  ellipse(x + 1, hullY + 1, w - 2, hullH - 2, M.c);
  if (litL) ellipse(x + 2, hullY + 2, w * 0.4, hullH * 0.55, M.d);
  else ellipse(x + w * 0.5, hullY + 2, w * 0.4, hullH * 0.55, M.d);
